"""Module dependency graph and deterministic plan ordering."""

import heapq
from collections import defaultdict


class DependencyGraph:
    """A graph whose edges point from a prerequisite to its dependent.

    ``dependencies[node]`` records prerequisite names.  Plan ordering is the
    lexicographically smallest topological order among currently eligible
    modules, restricted to the root's transitive prerequisite closure.
    """

    def __init__(self):
        self.nodes = set()
        self.dependencies = defaultdict(set)

    def add_node(self, node):
        self.nodes.add(node)

    def add_dependency(self, dependent, prerequisite):
        self.add_node(dependent)
        self.add_node(prerequisite)
        self.dependencies[dependent].add(prerequisite)

    # Compatibility helpers for the older toolkit API.
    def add_edge(self, prerequisite, dependent):
        self.add_dependency(dependent, prerequisite)

    def Edge(self, prerequisite, dependent):
        self.add_edge(prerequisite, dependent)

    def CallEdge(self, model, dependency_models):
        for dependency in dependency_models:
            self.add_dependency(model, dependency)

    def Pipe(self, target, filter_model):
        self.add_dependency(target, filter_model)

    def Node(self, model):
        self.add_node(model)

    def closure(self, root):
        seen = set()
        stack = [root]
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            stack.extend(self.dependencies.get(node, ()))
        return seen

    def compile_order(self, root):
        included = self.closure(root)
        indegree = {node: 0 for node in included}
        dependents = defaultdict(list)
        for node in included:
            prerequisites = {prerequisite
                             for prerequisite in self.dependencies.get(node, ())
                             if prerequisite in included}
            indegree[node] = len(prerequisites)
            for prerequisite in prerequisites:
                dependents[prerequisite].append(node)
        ready = [node for node, degree in indegree.items() if degree == 0]
        heapq.heapify(ready)
        order = []
        while ready:
            node = heapq.heappop(ready)
            order.append(node)
            for dependent in dependents.get(node, ()):
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    heapq.heappush(ready, dependent)
        if len(order) != len(included):
            raise ValueError("module dependency cycle")
        return order
