"""Corpus identity helpers.

The key is deliberately structural and tagged.  In particular ``True`` and
``1`` are different corpus values, and an empty array is different from an
empty object, even though Python's ordinary equality would merge some of them.
"""

from .model import (ArrayType, BoolType, CharType, EnumType, IntType,
                    StringType, StructType, VoidType, underlying)


def freeze_value(value, type_node):
    type_node = underlying(type_node)
    if isinstance(type_node, BoolType):
        return ("bool", value)
    if isinstance(type_node, CharType):
        return ("char", value)
    if isinstance(type_node, IntType):
        return ("int", value)
    if isinstance(type_node, StringType):
        return ("string", value)
    if isinstance(type_node, EnumType):
        return ("enum", value)
    if isinstance(type_node, ArrayType):
        return ("array", tuple(freeze_value(item, type_node.element)
                               for item in value))
    if isinstance(type_node, StructType):
        return ("struct", tuple((field_name,
                                 freeze_value(value[field_name], field_type))
                                for field_name, field_type in type_node.fields))
    if isinstance(type_node, VoidType):
        return ("void",)
    return ("unknown", repr(value))


def corpus_key(entry, inputs, parameter_types):
    """Return a hashable identity for ``(entry, recovered input values)``."""
    return (entry, tuple((name, freeze_value(inputs[name], type_node))
                         for name, type_node in parameter_types))
